<?php require_once __DIR__ . '/../includes/functions.php'; admin_header('Prescriptions'); $file=basename(__FILE__); $rows=db_fetch_all("SELECT pr.*,pc.case_code,u.name doctor_name FROM prescriptions pr JOIN patient_cases pc ON pc.id=pr.case_id LEFT JOIN users u ON u.id=pr.doctor_id ORDER BY pr.id DESC LIMIT 100"); $cols=['prescription_code', 'case_code', 'status', 'doctor_name', 'created_at']; ?><div class="card soft-card"><div class="card-body table-responsive"><table class="table table-hover"><thead><tr><?php foreach($cols as $c): ?><th><?= e(str_replace('_',' ',ucfirst($c))) ?></th><?php endforeach; ?><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php foreach($cols as $c): ?><td><?= e(excerpt((string)($r[$c] ?? ''), 120)) ?></td><?php endforeach; ?><?php if($file==='orders.php') echo '<td><a class="btn btn-sm btn-outline-success" href="order-view.php?id='.(int)$r['id'].'">View</a></td>'; elseif($file==='prescriptions.php') echo '<td><a class="btn btn-sm btn-outline-success" href="prescription-review.php?print='.(int)$r['id'].'">Print</a></td>'; else echo '<td></td>'; ?></tr><?php endforeach; ?></tbody></table><?php if(!$rows) echo empty_state('No records found.'); ?></div></div><?php admin_footer(); ?>
